/* ================================
   Maktoub Branding - Dark Mode Theme
   Based on Figma Design System
   ================================ */

:root {
    /* === Maktoub Color Palette === */
    /* Dark Mode (Primary) */
    --maktoub-dark: #102320;
    --maktoub-dark-rgb: 16, 35, 32;

    /* Primary Teal */
    --maktoub-primary: #1EA896;
    --maktoub-primary-rgb: 30, 168, 150;

    /* Light Teal (Accent) */
    --maktoub-light: #A0ECDC;
    --maktoub-light-rgb: 160, 236, 220;

    /* Teal Variations */
    --maktoub-teal-50: #F1FCFA;
    --maktoub-teal-300: #67E1CB;

    /* Neutral Colors */
    --maktoub-white: #FFFFFF;
    --maktoub-black: #000000;

    /* Border Colors */
    --maktoub-border: rgba(6, 100, 88, 0.5);
    --maktoub-border-light: rgba(160, 236, 220, 0.2);

    /* === Typography === */
    --font-primary: 'Cairo', 'Janna LT', 'Tajawal', sans-serif;
    --font-weight-regular: 400;
    --font-weight-bold: 700;

    /* Font Sizes */
    --text-xs: 12px;
    --text-sm: 14px;
    --text-base: 16px;
    --text-lg: 18px;
    --text-xl: 20px;
    --text-2xl: 24px;
    --text-3xl: 28px;
    --text-4xl: 32px;

    /* Line Heights */
    --leading-tight: 1.25;
    --leading-normal: 1.5;
    --leading-relaxed: 1.75;

    /* === Spacing === */
    --space-1: 4px;
    --space-2: 8px;
    --space-3: 12px;
    --space-4: 16px;
    --space-5: 20px;
    --space-6: 24px;
    --space-8: 32px;
    --space-10: 40px;
    --space-12: 48px;
    --space-16: 64px;

    /* === Border Radius === */
    --radius-sm: 4px;
    --radius-md: 6px;
    --radius-lg: 8px;
    --radius-xl: 12px;
    --radius-2xl: 16px;
    --radius-full: 9999px;

    /* === Shadows === */
    --shadow-sm: 0px 1px 2px rgba(0, 0, 0, 0.05);
    --shadow-md: 0px 4px 6px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0px 10px 15px rgba(0, 0, 0, 0.1);
    --shadow-xl: 0px 20px 25px rgba(0, 0, 0, 0.15);

    /* === Component Specific === */
    --navbar-height: 78px;
    --button-padding: 9px 17px;
    --card-padding: var(--space-8);

    /* === Status Colors === */
    --color-success: #28a745;
    --color-warning: #ffa500;
    --color-danger: #dc3545;
    --color-info: var(--maktoub-primary);

    /* === Transitions === */
    --transition-fast: 150ms ease;
    --transition-base: 300ms ease;
    --transition-slow: 500ms ease;
}

/* ================================
   Dark Mode Application
   ================================ */

body {
    font-family: var(--font-primary);
    background-color: var(--maktoub-dark);
    color: var(--maktoub-white);
    direction: rtl;
    transition: background-color var(--transition-base), 
                color var(--transition-base);
    margin: 0;
    padding: 0;
    line-height: var(--leading-normal);
}

* {
    box-sizing: border-box;
}

/* ================================
   Navbar Styling
   ================================ */

.navbar {
    background-color: var(--maktoub-dark);
    border-bottom: 1px solid var(--maktoub-border);
    position: sticky;
    top: 0;
    z-index: 1000;
    height: var(--navbar-height);
}

.nav-container {
    max-width: 1440px;
    margin: 0 auto;
    padding: 20px 32px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 100%;
}

.logo {
    display: flex;
    align-items: center;
    gap: var(--space-3);
    font-size: var(--text-2xl);
    font-weight: var(--font-weight-bold);
    color: var(--maktoub-primary);
    text-decoration: none;
}

.logo img.maktoub-logo {
    height: 50px;
    width: auto;
    max-width: 250px;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: var(--space-10);
    margin: 0;
    padding: 0;
}

.nav-link {
    text-decoration: none;
    color: var(--maktoub-white);
    font-weight: var(--font-weight-regular);
    font-size: var(--text-base);
    line-height: 24px;
    display: flex;
    align-items: center;
    gap: var(--space-2);
    transition: color var(--transition-base);
    padding: 0px;
    border-radius: var(--radius-md);
    white-space: nowrap;
}

.nav-link:hover,
.nav-link.active {
    color: var(--maktoub-light);
}

.nav-link i {
    font-size: 18px;
}

/* ================================
   Buttons
   ================================ */

.cta-button,
.auth-button,
.btn-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 9px 17px;
    background-color: var(--maktoub-dark);
    border: 1px solid var(--maktoub-light);
    color: var(--maktoub-light);
    font-family: var(--font-primary);
    font-weight: var(--font-weight-bold);
    font-size: var(--text-base);
    line-height: 28px;
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-sm);
    cursor: pointer;
    transition: all var(--transition-base);
    text-decoration: none;
}

.cta-button:hover,
.auth-button:hover,
.btn-primary:hover {
    background-color: var(--maktoub-primary);
    border-color: var(--maktoub-primary);
    color: var(--maktoub-white);
    transform: translateY(-1px);
    box-shadow: var(--shadow-md);
}

.btn-secondary {
    background-color: transparent;
    border: 1px solid var(--maktoub-border);
    color: var(--maktoub-white);
}

.btn-secondary:hover {
    background-color: rgba(var(--maktoub-light-rgb), 0.1);
    border-color: var(--maktoub-light);
}

/* ================================
   Cards
   ================================ */

.feature-card,
.card {
    background-color: rgba(var(--maktoub-light-rgb), 0.05);
    border: 1px solid var(--maktoub-border-light);
    border-radius: var(--radius-lg);
    padding: var(--card-padding);
    transition: all var(--transition-base);
}

.feature-card:hover,
.card:hover {
    background-color: rgba(var(--maktoub-light-rgb), 0.08);
    border-color: var(--maktoub-light);
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.feature-card i {
    color: var(--maktoub-primary);
    font-size: var(--text-4xl);
    margin-bottom: var(--space-4);
}

.feature-card h3 {
    color: var(--maktoub-white);
    font-size: var(--text-xl);
    font-weight: var(--font-weight-bold);
    margin-bottom: var(--space-3);
}

.feature-card p {
    color: rgba(var(--maktoub-light-rgb), 0.8);
    font-size: var(--text-base);
    line-height: var(--leading-relaxed);
    margin-bottom: var(--space-5);
}

/* ================================
   Forms
   ================================ */

.form-group {
    margin-bottom: var(--space-5);
}

.form-label {
    display: block;
    color: var(--maktoub-white);
    font-weight: var(--font-weight-regular);
    font-size: var(--text-base);
    margin-bottom: var(--space-2);
}

.form-input,
.form-select,
.form-textarea {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    background-color: rgba(var(--maktoub-light-rgb), 0.05);
    border: 1px solid var(--maktoub-border);
    border-radius: var(--radius-md);
    color: var(--maktoub-white);
    font-family: var(--font-primary);
    font-size: var(--text-base);
    transition: all var(--transition-base);
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
    outline: none;
    border-color: var(--maktoub-light);
    background-color: rgba(var(--maktoub-light-rgb), 0.08);
    box-shadow: 0 0 0 3px rgba(var(--maktoub-light-rgb), 0.1);
}

.form-input::placeholder,
.form-textarea::placeholder {
    color: rgba(var(--maktoub-light-rgb), 0.5);
}

/* ================================
   Theme Toggle
   ================================ */

.theme-toggle {
    background: transparent;
    border: 1px solid var(--maktoub-border);
    font-size: var(--text-xl);
    cursor: pointer;
    color: var(--maktoub-light);
    padding: var(--space-2);
    border-radius: var(--radius-full);
    transition: all var(--transition-base);
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.theme-toggle:hover {
    background-color: rgba(var(--maktoub-light-rgb), 0.1);
    border-color: var(--maktoub-light);
}

/* ================================
   Utility Classes
   ================================ */

.text-center {
    text-align: center;
}

.text-primary {
    color: var(--maktoub-primary);
}

.text-light {
    color: var(--maktoub-light);
}

.text-white {
    color: var(--maktoub-white);
}

.text-muted {
    color: rgba(var(--maktoub-light-rgb), 0.6);
}

.mb-2 { margin-bottom: var(--space-2); }
.mb-3 { margin-bottom: var(--space-3); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-5 { margin-bottom: var(--space-5); }
.mb-6 { margin-bottom: var(--space-6); }

.mt-2 { margin-top: var(--space-2); }
.mt-3 { margin-top: var(--space-3); }
.mt-4 { margin-top: var(--space-4); }
.mt-5 { margin-top: var(--space-5); }
.mt-6 { margin-top: var(--space-6); }

.p-2 { padding: var(--space-2); }
.p-3 { padding: var(--space-3); }
.p-4 { padding: var(--space-4); }
.p-5 { padding: var(--space-5); }
.p-6 { padding: var(--space-6); }

/* ================================
   Responsive Design
   ================================ */

@media (max-width: 768px) {
    .nav-container {
        padding: 16px 20px;
    }

    .nav-links {
        gap: var(--space-4);
        font-size: var(--text-sm);
    }

    .feature-cards {
        flex-direction: column;
    }

    .card-padding {
        padding: var(--space-5);
    }
}

@media (max-width: 480px) {
    .nav-links {
        display: none;
    }

    .logo {
        font-size: var(--text-lg);
    }
}

