}

/* Hero Section - Light Mode */
body.light-mode .hero-section {
    background-color: transparent;
}

body.light-mode .hero-title {
    color: var(--maktoub-dark);
}

body.light-mode .hero-subtitle {
    color: rgba(var(--maktoub-dark-rgb), 0.7);
}

/* Tables - Light Mode */
body.light-mode table {
    background-color: var(--maktoub-white);
    border: 1px solid rgba(var(--maktoub-primary-rgb), 0.15);
}

body.light-mode thead {
    background-color: rgba(var(--maktoub-primary-rgb), 0.05);
}

body.light-mode th,
body.light-mode td {
    border-color: rgba(var(--maktoub-primary-rgb), 0.1);
    color: var(--maktoub-dark);
}

body.light-mode tr:hover {
    background-color: rgba(var(--maktoub-primary-rgb), 0.02);
}

/* Profile - Light Mode */
body.light-mode .profile-menu,
body.light-mode .profile-dropdown {
    background-color: var(--maktoub-white);
    border: 1px solid rgba(var(--maktoub-primary-rgb), 0.15);
    box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.1);
