}

.avatar-icon {
    width: 32px;
    height: 32px;
    color: var(--white);
}

/* Dark mode avatar icon */
body.dark-mode .avatar-icon {
    color: var(--white);
}

/* Light mode avatar icon */
body:not(.dark-mode) .avatar-icon {
    color: var(--text-dark);
}

.avatar-image {
