    height: 32px;
    border-radius: 16px;
    object-fit: cover;
}

.profile-name {
    color: var(--white);
    font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
    font-size: 16px;
    font-style: normal;
    font-weight: 400;
    line-height: 20px;
}

.chevron-icon {
    width: 20px;
    height: 20px;
    transition: transform 0.3s ease;
}

.navbar-profile.active .chevron-icon {
