/**
 * Application Constants
 * Centralized constants for magic strings, numbers, and enums
 */

const AppConstants = (() => {
  // Letter Status Constants
  const LETTER_STATUS = {
    PENDING: 'pending',
    APPROVED: 'approved',
    REJECTED: 'rejected',
    DRAFT: 'draft',
    IN_REVIEW: 'in_review',
  };

  // Letter Types
  const LETTER_TYPES = {
    FIRST: 'first',
    FOLLOW_UP: 'follow_up',
    REPLY: 'reply',
  };

  // HTTP Status Codes
  const HTTP_STATUS = {
    OK: 200,
    CREATED: 201,
    BAD_REQUEST: 400,
    UNAUTHORIZED: 401,
    FORBIDDEN: 403,
    NOT_FOUND: 404,
    METHOD_NOT_ALLOWED: 405,
    INTERNAL_SERVER_ERROR: 500,
    SERVICE_UNAVAILABLE: 503,
  };

  // Notification Types
  const NOTIFICATION_TYPES = {
    SUCCESS: 'success',
    ERROR: 'error',
    WARNING: 'warning',
    INFO: 'info',
    LOADING: 'loading',
  };

  // Font Awesome Icons
  const ICONS = {
    SUCCESS: 'fa-check-circle',
    ERROR: 'fa-exclamation-circle',
    WARNING: 'fa-exclamation-triangle',
    INFO: 'fa-info-circle',
    MOON: 'fa-moon',
    SUN: 'fa-sun',
    LOADING: 'fa-spinner fa-spin',
    LOGOUT: 'fa-sign-out-alt',
    USER: 'fa-user',
    EDIT: 'fa-edit',
    DELETE: 'fa-trash',
    DOWNLOAD: 'fa-download',
    PRINT: 'fa-print',
    CLOSE: 'fa-times',
    CHECK: 'fa-check',
    QUESTION: 'fa-question-circle',
  };

  // Default Values
  const DEFAULTS = {
    RECIPIENT_TITLE: 'لا يوجد لقب',
    RECIPIENT_NAME: 'لا يوجد',
    EMPTY_VALUE: '',
    OTHER_OPTION: 'أخرى',
  };

  // Date Formats
  const DATE_FORMATS = {
    ISO: 'YYYY-MM-DD',
    ARABIC: 'DD/MM/YYYY',
    HIJRI: 'iDD/iMM/iYYYY',
  };

  // Regular Expressions
  const REGEX = {
    EMAIL: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
    PHONE: /^[\d\s+()-]+$/,
    GOOGLE_DRIVE_FILE_ID: /\/file\/d\/([a-zA-Z0-9-_]+)|open\?id=([a-zA-Z0-9-_]+)|id=([a-zA-Z0-9-_]+)/,
    WHITESPACE: /\s+/g,
  };

  // API Endpoints
  const ENDPOINTS = {
    // Authentication endpoints
    USER_VALIDATE: 'user/validate',
    USER_CREATE: 'user/create-user',
    USER_CLIENT: 'user/client',
    USER_CLIENTS: 'user/clients',

    // Letter endpoints
    LETTER_GENERATE: 'letter/generate',
    LETTER_VALIDATE: 'letter/validate',
    LETTER_CATEGORIES: 'letter/categories',
    LETTER_TEMPLATES: 'letter/templates',
    LETTER_HEALTH: 'letter/health',

    // Chat endpoints
    CHAT_SESSIONS: 'chat/sessions',
    CHAT_EDIT: 'chat/sessions',  // + /:session_id/edit
    CHAT_HISTORY: 'chat/sessions',  // + /:session_id/history
    CHAT_STATUS: 'chat/sessions',  // + /:session_id/status
    CHAT_EXTEND: 'chat/sessions',  // + /:session_id/extend
    CHAT_DELETE: 'chat/sessions',  // + /:session_id (DELETE)
    CHAT_HEALTH: 'chat/health',

    // Archive endpoints
    ARCHIVE_LETTER: 'archive/letter',
    ARCHIVE_STATUS: 'archive/status',  // + /:letter_id
    ARCHIVE_UPDATE: 'archive/update',
    ARCHIVE_HEALTH: 'archive/health',

    // Submissions endpoints
    SUBMISSIONS: 'submissions',
    SUBMISSIONS_SINGLE: 'submissions',  // + /:submission_id
    SUBMISSIONS_STATS: 'submissions/stats',

    // Health checks
    USER_HEALTH: 'user/health',
  };

  // CSS Classes
  const CSS_CLASSES = {
    DARK_MODE: 'dark-mode',
    ACTIVE: 'active',
    HIDDEN: 'hidden',
    LOADING: 'loading',
    ERROR: 'error',
    SUCCESS: 'success',
    DISABLED: 'disabled',
    NOTIFICATION_SHOW: 'notification-show',
    NOTIFICATION_HIDE: 'notification-hide',
  };

  // Error Messages (Arabic)
  const ERROR_MESSAGES = {
    NETWORK_ERROR: 'حدث خطأ في الاتصال بالخادم',
    INVALID_EMAIL: 'البريد الإلكتروني غير صحيح',
    INVALID_PASSWORD: 'كلمة المرور غير صحيحة',
    LOGIN_FAILED: 'فشل تسجيل الدخول',
    SIGNUP_FAILED: 'فشل إنشاء الحساب',
    LETTER_GENERATION_FAILED: 'فشل إنشاء الخطاب',
    LETTER_VALIDATION_FAILED: 'فشل التحقق من الخطاب',
    UNAUTHORIZED: 'غير مصرح لك بالوصول',
    SESSION_EXPIRED: 'انتهت الجلسة، الرجاء تسجيل الدخول مرة أخرى',
    UNKNOWN_ERROR: 'حدث خطأ غير معروف',
    REQUIRED_FIELD: 'هذا الحقل مطلوب',
    DOMAIN_NOT_ALLOWED: 'النطاق غير مسموح به',
  };

  // Success Messages (Arabic)
  const SUCCESS_MESSAGES = {
    LOGIN_SUCCESS: 'تم تسجيل الدخول بنجاح',
    SIGNUP_SUCCESS: 'تم إنشاء الحساب بنجاح',
    LETTER_GENERATED: 'تم إنشاء الخطاب بنجاح',
    LETTER_SAVED: 'تم حفظ الخطاب بنجاح',
    LETTER_UPDATED: 'تم تحديث الخطاب بنجاح',
    LETTER_DELETED: 'تم حذف الخطاب بنجاح',
    LOGOUT_SUCCESS: 'تم تسجيل الخروج بنجاح',
  };

  // Loading Messages (Arabic)
  const LOADING_MESSAGES = {
    LOADING: 'جاري التحميل...',
    GENERATING_LETTER: 'جاري إنشاء الخطاب...',
    VALIDATING_LETTER: 'جاري التحقق من الخطاب...',
    SAVING: 'جاري الحفظ...',
    LOGGING_IN: 'جاري تسجيل الدخول...',
    PROCESSING: 'جاري المعالجة...',
  };

  // Return public constants object
  return {
    LETTER_STATUS,
    LETTER_TYPES,
    HTTP_STATUS,
    NOTIFICATION_TYPES,
    ICONS,
    DEFAULTS,
    DATE_FORMATS,
    REGEX,
    ENDPOINTS,
    CSS_CLASSES,
    ERROR_MESSAGES,
    SUCCESS_MESSAGES,
    LOADING_MESSAGES,
  };
})();

// Export for browser
if (typeof window !== 'undefined') {
  window.AppConstants = AppConstants;
}

// Export for Node.js (server-side)
if (typeof module !== 'undefined' && module.exports) {
  module.exports = AppConstants;
}

css/maktoub-auth.css.content:
/* ================================
   Maktoub Authentication Styles
   Dark Mode Theme
   ================================ */

.auth-container {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background-color: var(--maktoub-dark);
    background-image: 
        radial-gradient(at 20% 80%, rgba(var(--maktoub-light-rgb), 0.1) 0px, transparent 50%),
        radial-gradient(at 80% 20%, rgba(var(--maktoub-primary-rgb), 0.1) 0px, transparent 50%);
    padding: var(--space-5);
}

.auth-box {
    background-color: rgba(var(--maktoub-light-rgb), 0.05);
    backdrop-filter: blur(10px);
    border: 1px solid var(--maktoub-border);
    padding: var(--space-10);
    border-radius: var(--radius-2xl);
    box-shadow: var(--shadow-xl);
    width: 100%;
    max-width: 440px;
    text-align: center;
}

.auth-box .logo {
    margin-bottom: var(--space-6);
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: var(--space-3);
}

.auth-box .logo img.maktoub-logo {
    height: 60px;
    width: auto;
    max-width: 100%;
}

.auth-box .logo span {
    color: var(--maktoub-primary);
    font-size: var(--text-2xl);
    font-weight: var(--font-weight-bold);
}

.auth-box h2 {
    color: var(--maktoub-white);
    font-size: var(--text-3xl);
    font-weight: var(--font-weight-bold);
    margin-bottom: var(--space-8);
    line-height: var(--leading-tight);
}

/* Google Sign-In Button */
.google-signin-container {
    margin-bottom: var(--space-5);
    width: 100%;
}

.google-signin-container .g_id_signin {
    width: 100% !important;
    display: flex !important;
    justify-content: center !important;
}

/* Divider */
.divider {
    display: flex;
    align-items: center;
    margin: var(--space-6) 0;
    color: rgba(var(--maktoub-light-rgb), 0.6);
    font-size: var(--text-sm);
}

.divider::before,
.divider::after {
    content: "";
    flex: 1;
    height: 1px;
    background: var(--maktoub-border);
}

.divider span {
    padding: 0 var(--space-4);
    background: transparent;
}

/* Form Styling */
.auth-form .form-group {
    margin-bottom: var(--space-5);
    text-align: right;
}

.auth-form label {
    display: block;
    color: var(--maktoub-white);
    font-weight: var(--font-weight-regular);
    font-size: var(--text-base);
    margin-bottom: var(--space-2);
    text-align: right;
}

.auth-form input {
    width: 100%;
    padding: var(--space-3) var(--space-4);
    background-color: rgba(var(--maktoub-light-rgb), 0.05);
    border: 1px solid var(--maktoub-border);
    border-radius: var(--radius-md);
    color: var(--maktoub-white);
    font-family: var(--font-primary);
    font-size: var(--text-base);
    transition: all var(--transition-base);
    direction: rtl;
}

.auth-form input:focus {
    outline: none;
    border-color: var(--maktoub-light);
    background-color: rgba(var(--maktoub-light-rgb), 0.08);
    box-shadow: 0 0 0 3px rgba(var(--maktoub-light-rgb), 0.1);
}

.auth-form input::placeholder {
    color: rgba(var(--maktoub-light-rgb), 0.5);
}

/* Auth Button */
.auth-button {
    width: 100%;
    padding: var(--space-4) var(--space-5);
    background-color: var(--maktoub-primary);
    border: 1px solid var(--maktoub-primary);
    color: var(--maktoub-white);
    font-family: var(--font-primary);
    font-weight: var(--font-weight-bold);
    font-size: var(--text-base);
    line-height: 28px;
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-sm);
    cursor: pointer;
    transition: all var(--transition-base);
    margin-top: var(--space-3);
}

.auth-button:hover {
    background-color: var(--maktoub-light);
    border-color: var(--maktoub-light);
    color: var(--maktoub-dark);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.auth-button:active {
    transform: translateY(0);
}

.auth-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    transform: none;
}

/* Links */
.auth-link {
    display: inline-block;
    margin-top: var(--space-4);
    color: var(--maktoub-light);
    font-size: var(--text-sm);
    text-decoration: none;
    transition: color var(--transition-base);
}

.auth-link:hover {
    color: var(--maktoub-primary);
    text-decoration: underline;
}

.auth-footer {
    margin-top: var(--space-6);
    color: rgba(var(--maktoub-light-rgb), 0.6);
    font-size: var(--text-sm);
}

/* Error Messages */
.error-message {
    background-color: rgba(220, 53, 69, 0.1);
    border: 1px solid rgba(220, 53, 69, 0.3);
    color: #ff6b6b;
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-md);
    margin-bottom: var(--space-4);
    font-size: var(--text-sm);
    text-align: center;
}

.success-message {
    background-color: rgba(40, 167, 69, 0.1);
    border: 1px solid rgba(40, 167, 69, 0.3);
    color: #51cf66;
