    font-size: 0.85rem;
}

body.dark-mode .letters-table td {
    border-bottom-color: var(--border-dark);
}

/* Text handling in cells */
.letters-table td {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    vertical-align: middle;
}

/* Allow text wrapping for subject and notes columns */
.letters-table td:nth-child(7), /* الموضوع */
.letters-table td:nth-child(9) { /* الملاحظات */
    white-space: normal;
    word-wrap: break-word;
    line-height: 1.3;
    max-height: 3.6em;
