}

body.dark-mode .letters-table tbody tr:hover {
    background-color: rgba(0, 166, 81, 0.1);
}

/* Status badges */
.status-badge {
    padding: 0.2rem 0.5rem;
    border-radius: 20px;
    font-size: 0.7rem;
    font-weight: 600;
    display: inline-block;
    white-space: nowrap;
}

.status-ready {
    background-color: rgba(40, 167, 69, 0.2);
    color: var(--success);
}

