    color: var(--danger);
}

/* Action buttons styling */
.action-buttons {
    display: flex;
    gap: 0.2rem;
    justify-content: center;
    flex-wrap: nowrap;
    align-items: center;
}

.action-icon {
    background: none;
    border: none;
    color: var(--primary-color);
    font-size: 0.9rem;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 4px;
    transition: all 0.3s ease;
    min-width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.action-icon:hover {
    background-color: rgba(0, 166, 81, 0.1);
    transform: scale(1.1);
}

.action-icon.delete {
