}

.no-data i {
    font-size: 4rem;
    color: var(--border-light);
    margin-bottom: 1rem;
}

body.dark-mode .no-data i {
    color: var(--border-dark);
}

/* Highlighted letter row styling */
.highlighted-letter {
    background-color: rgba(0, 166, 81, 0.1) !important;
    border: 2px solid var(--primary-color);
    animation: highlight-pulse 2s ease-in-out;
}

body.dark-mode .highlighted-letter {
    background-color: rgba(0, 166, 81, 0.2) !important;
}

@keyframes highlight-pulse {
    0% {
        box-shadow: 0 0 5px rgba(0, 166, 81, 0.5);
    }
    50% {
        box-shadow: 0 0 20px rgba(0, 166, 81, 0.8);
    }
    100% {
        box-shadow: 0 0 10px rgba(0, 166, 81, 0.3);
    }
}

/* Responsive adjustments */
@media (max-width: 1400px) {
    .letters-table th,
    .letters-table td {
        padding: 0.5rem 0.25rem;
        font-size: 0.8rem;
    }

