    .letters-table th,
    .letters-table td {
        padding: 0.4rem 0.2rem;
        font-size: 0.75rem;
    }

    .action-icon {
        font-size: 0.8rem;
        min-width: 20px;
        height: 20px;
        padding: 0.15rem;
    }

    .status-badge {
