/* Letter Validation Display Styles - Add to styles.css */

.validation-section {
    background-color: var(--card-light);
    border: 1px solid var(--border-light);
    border-radius: 12px;
    padding: 1.5rem;
    margin-top: 1.5rem;
}

body.dark-mode .validation-section {
    background-color: var(--card-dark);
    border-color: var(--border-dark);
}

.validation-section h4 {
    margin: 0 0 1rem 0;
    color: var(--primary-color);
    font-size: 1.1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.validation-content {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

/* Validation Status */
.validation-status {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem;
    border-radius: 8px;
    font-weight: 600;
    font-size: 1rem;
}

.status-valid {
    background-color: rgba(40, 167, 69, 0.1);
    color: var(--success);
    border: 1px solid rgba(40, 167, 69, 0.3);
}

.status-invalid {
    background-color: rgba(220, 53, 69, 0.1);
    color: var(--danger);
    border: 1px solid rgba(220, 53, 69, 0.3);
}

.validation-status i {
    font-size: 1.2rem;
}

/* Validation Checks */
.validation-checks h5,
.validation-metrics h5,
.validation-suggestions h5 {
    margin: 0 0 0.75rem 0;
    color: var(--text-light);
    font-size: 1rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

body.dark-mode .validation-checks h5,
body.dark-mode .validation-metrics h5,
body.dark-mode .validation-suggestions h5 {
    color: var(--text-dark);
}

.checks-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 0.75rem;
}

.check-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem;
    border-radius: 6px;
    font-size: 0.9rem;
    border: 1px solid;
}

.check-passed {
    background-color: rgba(40, 167, 69, 0.1);
    color: var(--success);
    border-color: rgba(40, 167, 69, 0.3);
}

.check-failed {
    background-color: rgba(220, 53, 69, 0.1);
    color: var(--danger);
    border-color: rgba(220, 53, 69, 0.3);
}

.check-item i {
    font-size: 1rem;
    flex-shrink: 0;
}

/* Validation Metrics */
.metrics-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 1rem;
}

.metric-item {
    background-color: rgba(0, 166, 81, 0.05);
    border: 1px solid rgba(0, 166, 81, 0.2);
    border-radius: 6px;
    padding: 1rem;
    text-align: center;
}

body.dark-mode .metric-item {
